def sort_array(arr):
    '''Sorts a list of numbers based on the sum of the first and last elements.
    If the sum is odd, returns a new list sorted in ascending order; if even, a new list sorted in descending order.
    Raises AttributeError for non-list inputs.'''
    if not isinstance(arr, list):
        raise AttributeError("Input must be a list")
    if len(arr) == 0:
        return []
    total = arr[0] + arr[-1]
    if total % 2:
        return sorted(arr)
    else:
        return sorted(arr, reverse=True)

